// Audit site taxonomy and identify state x practice area gaps
const posts = $items('Crawl Live WordPress Posts').map(p => p.json);
const categories = $items('Fetch WordPress Categories').map(c => c.json);
const existingBank = $items('Read Existing Topic Bank').map(t => (t.json.title_idea || '').toLowerCase());

const keyStates = ['Texas', 'Missouri', 'California', 'Florida', 'New York', 'Illinois', 'Georgia', 'Ohio', 'Pennsylvania', 'North Carolina'];
const practiceAreas = ['Family Law', 'Estate Planning', 'Corporate & LLC', 'Criminal Defense', 'Personal Injury', 'Employment Law', 'Real Estate Law'];

// Matrix of coverage
const coverageMatrix = [];

for (const state of keyStates) {
  for (const practice of practiceAreas) {
    const matchCount = posts.filter(p => {
      const text = `${p.title?.rendered || ''} ${p.slug || ''}`.toLowerCase();
      return text.includes(state.toLowerCase()) && text.includes(practice.toLowerCase().split(' ')[0]);
    }).length;

    // If under target threshold (e.g. 5 articles minimum per combo)
    if (matchCount < 5) {
      coverageMatrix.push({
        state: state,
        practiceArea: practice,
        currentCount: matchCount,
        deficit: 5 - matchCount
      });
    }
  }
}

// Sort by biggest deficits
coverageMatrix.sort((a, b) => b.deficit - a.deficit);
const topGaps = coverageMatrix.slice(0, 8);

return [{
  json: {
    totalAuditedPosts: posts.length,
    detectedGaps: topGaps,
    existingTopicCount: existingBank.length
  }
}];

// Parse AI generated gap recommendations and format for Google Sheets
const raw = $json.message?.content || $json.text || '';
let recommendations = [];

try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  recommendations = JSON.parse(cleaned);
} catch (e) {
  recommendations = [];
}

if (!Array.isArray(recommendations)) {
  recommendations = [];
}

const now = new Date().toISOString();
const rows = recommendations.map((item, idx) => ({
  json: {
    topic_id: `GAP-TOPIC-${Date.now()}-${idx + 1}`,
    title_idea: item.title_idea || 'Legal Analysis Guide',
    primary_keyword: item.primary_keyword || '',
    target_state: item.target_state || 'Federal',
    practice_area: item.practice_area || 'General Law',
    source_type: 'gap_analysis',
    relevance_score: Number(item.relevance_score) || 90,
    status: 'NEW',
    suggested_date: now.split('T')[0],
    notes: item.notes || 'Generated from nightly content gap analysis audit.',
    created_at: now
  }
}));

return rows.length > 0 ? rows : [{ json: { status: 'NO_NEW_GAP_TOPICS' } }];
